return (async()=>{
await new Promise(resolve=>setTimeout(resolve,1500));
const before=(await tools.mcp__t3_code__preview_evaluate({tabId,expression:"({url:location.href,text:document.querySelector('main').innerText,links:[...document.querySelectorAll('main a')].map(a=>a.href)})"})).structuredContent.value;
if(!before.url.includes('/p/'+id))throw Error('Wrong problem page');
if(before.links.includes(paperUrl))return {duplicate:true,before};
const opened=await tools.mcp__t3_code__preview_evaluate({tabId,expression:"(()=>{const b=[...document.querySelectorAll('button')].find(e=>e.textContent==='Post a solution');if(!b)throw Error('No solution button');b.click();return true;})()"});
await tools.mcp__t3_code__preview_evaluate({tabId,expression:"new Promise(resolve=>{const obs=new MutationObserver(()=>{if(document.querySelector('textarea[aria-label=Summary]')){obs.disconnect();resolve(true)}});if(document.querySelector('textarea[aria-label=Summary]'))resolve(true);else obs.observe(document.body,{childList:true,subtree:true});})"});
const filled=(await tools.mcp__t3_code__preview_evaluate({tabId,expression:`(()=>{const s=${JSON.stringify(draft)};const set=(e,v)=>{Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set.call(e,v);e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}));};set(document.querySelector('textarea[aria-label="Summary"]'),s.summary);set(document.querySelector('textarea[placeholder="Write your solution…"]'),s.body);const label=document.querySelector('select[aria-label="Label"]');label.value=${JSON.stringify(label)};label.dispatchEvent(new Event('change',{bubbles:true}));return {summary:document.querySelector('textarea[aria-label="Summary"]').value,body:document.querySelector('textarea[placeholder="Write your solution…"]').value,label:label.value};})()`})).structuredContent.value;
if(filled.summary!==draft.summary||filled.body!==draft.body||filled.label!==label)throw Error('Solution form mismatch');
return await tools.mcp__t3_code__preview_evaluate({tabId,expression:"(()=>{const b=[...document.querySelectorAll('button')].find(e=>e.textContent==='Post solution');if(!b||b.disabled)throw Error('Submit unavailable');b.click();return 'submitted';})()"});
})()

processBackfillCode:
return (async()=>{
await tools.mcp__t3_code__preview_navigate({tabId,url:'https://mathdb.com/p/'+p.problem_id});
await new Promise(r=>setTimeout(r,1500));
const read=(await tools.mcp__t3_code__preview_evaluate({tabId,expression:cleanRead}));
if(read.isError||!read.structuredContent)throw Error(JSON.stringify(read));
const before=read.structuredContent.value;
if(before.title!==p.expected_problem_title+' | MathDB')throw Error('Changed title: '+JSON.stringify(before));
const existing=before.links.some(a=>a.href===p.url);
if(!existing){
 if(before.ids.some(x=>x.tag==='SECTION'&&x.id.startsWith('s')))throw Error('Other solution exists, inspect before posting: '+JSON.stringify(before));
 const submit=await new Function('tools','tabId','id','paperUrl','draft','label',startSolution)(tools,tabId,p.problem_id,p.url,{summary:p.summary,body:p.body},p.label);
 if(submit.isError)throw Error(JSON.stringify(submit));
 const waited=(await tools.mcp__t3_code__preview_evaluate({tabId,expression:new Function('url',waitSolution)(p.url)}));
 if(waited.structuredContent?.value!==true)throw Error('Solution did not become visible');
}
const observed=(await tools.mcp__t3_code__preview_evaluate({tabId,expression:readSolution})).structuredContent.value;
const q=x=>"'"+x.replace(/'/g,"'\\''")+"'";
const receipt=await tools.exec_command({cmd:"python output/submissions/2026-11-06-problem-links/record_link.py "+p.id+" "+q(JSON.stringify(observed))+(existing?' already_linked_verified':''),workdir:"/home/mj-kang/Documents/Dev/math/openai-proof-research"});
if(receipt.exit_code!==0)throw Error(JSON.stringify(receipt));
return receipt.output;
})()

