startPaperCode:
return (async()=>{
const snap=(await tools.mcp__t3_code__preview_snapshot({tabId})).structuredContent;
const tree=snap.accessibilityTree;
const refs={pdf:tree.match(/button "PDF file Choose PDF" \[ref=([^\]]+)/)?.[1],attach:tree.match(/button "Add files" \[ref=([^\]]+)/)?.[1],submit:tree.match(/button "Submit paper" \[ref=([^\]]+)/)?.[1]};
if(!refs.pdf||!refs.attach||!refs.submit)throw Error('Upload form not ready: '+snap.visibleText);
const fields=await tools.mcp__t3_code__preview_evaluate({tabId,expression:`(()=>{const p=${JSON.stringify(p)};const set=(e,v)=>{Object.getOwnPropertyDescriptor(e.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,'value').set.call(e,v);e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}));};set(document.getElementById('paper-title'),p.title);set(document.getElementById('paper-authors'),p.authors);set(document.querySelector('textarea:not(#paper-comments)'),p.abstract);set(document.getElementById('paper-comments'),p.comments);return document.getElementById('paper-title').value;})()`});
if(fields.structuredContent?.value!==p.title)throw Error('Title mismatch');
for(const [ref,paths] of [[refs.pdf,[p.paper]],...p.attachments.map(path=>[refs.attach,[path]])]){
const r=await tools.mcp__t3_code__preview_act({tabId,action:'upload',locator:'aria-ref='+ref,paths});if(r.isError)throw Error(JSON.stringify(r));
}
const verify=(await tools.mcp__t3_code__preview_evaluate({tabId,expression:"document.querySelector('main').innerText"})).structuredContent.value;
if(!verify.includes('proof-sources')||!verify.includes('extract_sources.py')||!verify.includes(p.paper.split('/').pop()))throw Error(verify);
const submit=await tools.mcp__t3_code__preview_act({tabId,action:'click',locator:'aria-ref='+refs.submit});
return {id:p.id,formVerified:true,submit};
})()
